#!/bin/bash
# Unit tests for the statistics classes (FisherExactTest, PoissonBinomial2, SingleCellTest,
# TestIndepPoiBinom, TestIndepPoiBinomOnBam, SingleBaseResHicMatrix, SingleBaseResHicMatrixV2).
#
# usage: bash test/unit/stats/run.sh [scratchDir]
#
# Compiles the main sources and the tests in this folder into <scratchDir> (default: a fresh
# mktemp directory; never target/) and runs every test in its own JVM. Exit code 0 = all passed.
# All inputs are synthetic and generated by the tests themselves.
#
# Environment:
#   JAVA_HOME     JDK (9 or newer, for --release 8) to use (default: Quest openjdk 11)
#   MAIN_CLASSES  directory of already compiled main classes to test instead of compiling the
#                 source tree (used to run the tests against a pre-fix build)
set -u
HERE=$(cd "$(dirname "$0")" && pwd)
R=$(cd "$HERE/../../.." && pwd)
JAVA_HOME=${JAVA_HOME:-/gpfs/software/spack_v20d1/spack/opt/spack/linux-rhel7-x86_64/gcc-10.4.0/openjdk-11.0.17_8-xt4o77czxlhvrycpl4jo3z5swnqihkvz}
SCRATCH=${1:-$(mktemp -d)}
mkdir -p "$SCRATCH/test_classes" "$SCRATCH/work"
DEPS="$R/target/bisulfitehic-0.38-jar-with-dependencies.jar:$R/lib/*:$R/jbwa/jbwa-1.0.0/jbwa.jar"

if [ -z "${MAIN_CLASSES:-}" ]; then
	MAIN_CLASSES="$SCRATCH/main_classes"
	mkdir -p "$MAIN_CLASSES"
	"$JAVA_HOME/bin/javac" -nowarn --release 8 -d "$MAIN_CLASSES" -cp "$DEPS" \
		"$R"/src/main/java/edu/mit/compbio/bisulfitehic/*/*.java 2> "$SCRATCH/javac_main.log" \
		|| { cat "$SCRATCH/javac_main.log"; echo "main sources failed to compile"; exit 2; }
fi

# freshly compiled classes must come before the production jar on the classpath
CP="$MAIN_CLASSES:$DEPS"
"$JAVA_HOME/bin/javac" -nowarn --release 8 -d "$SCRATCH/test_classes" -cp "$CP" "$HERE"/*.java \
	|| { echo "tests failed to compile"; exit 2; }

status=0
run_test() {
	# $1 = log name, remaining = test class and its arguments
	local name=$1
	shift
	"$JAVA_HOME/bin/java" -cp "$SCRATCH/test_classes:$CP" -Dtest.tmp="$SCRATCH/work" "$@" > "$SCRATCH/$name.log" 2>&1
	local rc=$?
	grep -E "^FAIL|checks passed" "$SCRATCH/$name.log"
	if [ $rc -ne 0 ]; then
		status=1
		grep -q -E "checks passed" "$SCRATCH/$name.log" || { echo "FAIL $name did not finish (exit $rc, see $SCRATCH/$name.log)"; tail -5 "$SCRATCH/$name.log"; }
	fi
}

run_test FisherExactTestTest FisherExactTestTest
run_test PoissonBinomial2Test PoissonBinomial2Test
run_test SingleCellTestOutputTest SingleCellTestOutputTest
run_test TestIndepPoiBinomWindowTest TestIndepPoiBinomWindowTest
run_test TestIndepPoiBinomOnBamTest TestIndepPoiBinomOnBamTest
run_test SingleBaseResHicMatrixTest_v1 SingleBaseResHicMatrixTest v1
run_test SingleBaseResHicMatrixTest_v2 SingleBaseResHicMatrixTest v2

echo "scratch directory: $SCRATCH"
if [ $status -eq 0 ]; then echo "ALL STATS TESTS PASSED"; else echo "SOME STATS TESTS FAILED"; fi
exit $status
